Okay, let's try a different exercise. How about we write a Python function that takes a string and returns a new string where all the words that have more than one 'e' are replaced with a question mark?

def replace_words(s):
    words = s.split()
    new_words = []

    for w in words:
        if w.count('e') > 1:
            new_words.append('?')
        else:
            new_words.append(w)

    return ' '.join(new_words)

print(replace_words("Are you having fun? Yes, I am!"))

