def get_jump():
  jump = 'JUMP'
  return jump

def get_outfit():
  outfit = 'OUTFIT'
  return outfit

def get_jump_outfit():
  jump = get_jump()
  outfit = get_outfit()
  return jump, outfit

if __name__ == "__main__":
  jump, outfit = get_jump_outfit()
  print(jump, outfit)

