from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route("/register")
def register():
    name = request.args.get("name")
    email = request.args.get("email")

    data = {
        "name": name,
        "email": email
    }

    html = "<h1>{}</h1><p>{}</p>".format(data["name"], data["email"])
    return html

